// Configuration variables are injected, avoiding hardcoded values
type Config struct {
    RedisPrefix string
    KafkaTopic string
    LockDuration time.Duration
}

type TicketService struct {
    redis *redis.Client
    kafka *kafka.Writer
    config *Config
}

// Clean error handling variables
var (
    ErrStockDepleted = errors.New("STK_001: ticket stock has been depleted")
    ErrLockFailed = errors.New("LCK_001: failed to acquire distributed lock")
    ErrInternal = errors.New("SYS_500: internal system error")
)

func (s *TicketService) BookTicket(ctx context.Context, userID, eventID string) error {
    if userID == "" || eventID == "" {
        return fmt.Errorf("validation error: userID and eventID are required")
    }

    lockKey := fmt.Sprintf("%s:lock:%s", s.config.RedisPrefix, eventID)
    stockKey := fmt.Sprintf("%s:stock:%s", s.config.RedisPrefix, eventID)

    // 1. Acquire Distributed Lock (Mencegah Race Condition)
    locked, err := s.redis.SetNX(ctx, lockKey, userID, s.config.LockDuration).Result()
    if err != nil {
        return fmt.Errorf("redis error during lock acquisition: %w", err)
    }
    if !locked {
        return ErrLockFailed
    }

    // 2. Ensure lock is strictly released
    defer func() {
        if delErr := s.redis.Del(ctx, lockKey).Err(); delErr != nil {
            fmt.Printf("CRITICAL: Failed to release lock for %s: %v\n", lockKey, delErr)
        }
    }()

    // 3. Evaluasi Stok
    stock, err := s.redis.Get(ctx, stockKey).Int()
    if err != nil {
        if errors.Is(err, redis.Nil) {
            return ErrStockDepleted
        }
        return fmt.Errorf("failed to retrieve stock: %w", err)
    }
    if stock <= 0 {
        return ErrStockDepleted
    }

    // 4. Dekrementasi Stok secara Atomik
    if err := s.redis.Decr(ctx, stockKey).Err(); err != nil {
        return fmt.Errorf("failed to decrement stock: %w", err)
    }

    // 5. Publikasi Event ke Kafka (Asynchronous Processing)
    msgPayload := fmt.Sprintf(`{"user_id":"%s", "event_id":"%s", "timestamp":"%s"}`,
        userID, eventID, time.Now().UTC().Format(time.RFC3339))

    message := kafka.Message{
        Key: []byte(userID),
        Value: []byte(msgPayload),
    }

    if err := s.kafka.WriteMessages(ctx, message); err != nil {
        // Fallback / Compensating Transaction: Rollback stok Redis
        s.redis.Incr(ctx, stockKey)
        return fmt.Errorf("failed to publish to Kafka, stock rolled back: %w", err)
    }

    return nil
}

