// Java record sangat cocok untuk Value Object: immutable & ringkas
public record Money(BigDecimal amount, String currency) {

    public Money {
        if (amount.signum() < 0)
            throw new IllegalArgumentException("Jumlah tidak boleh negatif");
    }

    public Money add(Money other) {
        if (!currency.equals(other.currency))
            throw new IllegalArgumentException("Mata uang berbeda");
        return new Money(amount.add(other.amount), currency);
    }
}

public class Order {                 // Aggregate Root
    private final OrderId id;        // identitas (Value Object)
    private OrderStatus status;
    private final List<OrderItem> items = new ArrayList<>();

    public void addItem(Product product, int qty) {
        // aturan bisnis dijaga di dalam aggregate
        if (status != OrderStatus.DRAFT)
            throw new IllegalStateException("Order terkunci, tidak bisa diubah");
        items.add(new OrderItem(product.id(), qty, product.price()));
    }

    public Money total() {
        return items.stream()
            .map(OrderItem::subtotal)
            .reduce(new Money(BigDecimal.ZERO, "IDR"), Money::add);
    }

    // 'items' tidak diekspos langsung agar tidak diubah dari luar aggregate
    public List<OrderItem> items() {
        return Collections.unmodifiableList(items);
    }
}

