@Service
public class PlaceOrderService {
    private final OrderRepository repository;
    private final ApplicationEventPublisher events;

    public PlaceOrderService(OrderRepository r, ApplicationEventPublisher e) {
        this.repository = r;
        this.events = e;
    }

    public void place(Order order) {
        order.place();                  // ubah status -> PLACED (aturan di aggregate)
        repository.save(order);
        events.publishEvent(new OrderPlacedEvent(
            order.id(), order.total(), Instant.now()));
    }
}

import java.math.BigDecimal;

// Value Object: Immutable & Self-Validating
public record Money(BigDecimal amount, String currency) {

    // Externalized constants for clean error handling
    public static final String ERR_NEGATIVE = "VAL_001: Amount cannot be negative";
    public static final String ERR_CURRENCY_MISMATCH = "VAL_002: Currency mismatch
during operation";
    public static final String ERR_EMPTY_CURRENCY = "VAL_003: Currency cannot be
empty";

    public Money {
        if (amount == null || amount.signum() < 0) {
            throw new IllegalArgumentException(ERR_NEGATIVE);
        }
        if (currency == null || currency.isBlank()) {
            throw new IllegalArgumentException(ERR_EMPTY_CURRENCY);
        }
    }

    public Money add(Money other) {
        if (other == null || !this.currency.equals(other.currency)) {
            throw new IllegalArgumentException(ERR_CURRENCY_MISMATCH);
        }
        return new Money(this.amount.add(other.amount), this.currency);
    }
}

