@Service
public class ProductService {

    private final ProductRepository repository;

    public ProductService(ProductRepository repository) {
        this.repository = repository;
    }

    // Cache-aside: cek cache "products" dulu. Jika miss, jalankan
    // method ini dan simpan hasilnya dengan key = id.
    @Cacheable(value = "products", key = "#id")
    public Product getById(Long id) {
        System.out.println("Mengambil dari DATABASE untuk id: " + id);
        return repository.findById(id)
            .orElseThrow(() -> new RuntimeException("Produk tidak ditemukan"));
    }

    // Perbarui DB sekaligus perbarui isi cache dengan hasil terbaru.
    @CachePut(value = "products", key = "#product.id")
    public Product update(Product product) {
        return repository.save(product);
    }

    // Hapus data dari cache saat produk dihapus (cache invalidation).
    @CacheEvict(value = "products", key = "#id")
    public void delete(Long id) {
        repository.deleteById(id);
    }

    // Kosongkan seluruh cache "products".
    @CacheEvict(value = "products", allEntries = true)
    public void clearAll() { }
}

@Configuration
public class RabbitConfig {

    public static final String QUEUE = "order.queue";
    public static final String EXCHANGE = "order.exchange";
    public static final String ROUTING_KEY = "order.created";

    @Bean
    public Queue orderQueue() {
        return QueueBuilder.durable(QUEUE)
            .withArgument("x-dead-letter-exchange", "order.dlx") // arahkan ke DLQ
            .build();
    }

    @Bean
    public TopicExchange orderExchange() {
        return new TopicExchange(EXCHANGE);
    }

    @Bean
    public Binding binding(Queue orderQueue, TopicExchange orderExchange) {
        return BindingBuilder.bind(orderQueue).to(orderExchange).with(ROUTING_KEY);
    }

    @Bean
    public Jackson2JsonMessageConverter converter() {
        return new Jackson2JsonMessageConverter();
    }
}

