@Service
public class InventoryService {

    private final WebClient webClient;

    public InventoryService(WebClient.Builder builder) {
        this.webClient = builder.baseUrl("http://inventory-service").build();
    }

    // fallbackMethod dipanggil saat gagal / circuit terbuka.
    @CircuitBreaker(name = "inventoryService", fallbackMethod = "fallbackStock")
    @Retry(name = "inventoryService")
    public Integer getStock(Long productId) {
        return webClient.get()
            .uri("/stock/{id}", productId)
            .retrieve()
            .bodyToMono(Integer.class)
            .block();
    }

    public Integer fallbackStock(Long productId, Throwable t) {
        System.out.println("Fallback aktif: " + t.getMessage());
        return 0; // nilai cadangan yang aman, mis. anggap stok 0
    }
}

